1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.web.bind.annotation.RequestParam;
6	
7	/**
8	 * GET /api/notes?targetType=&lt;type&gt;&amp;targetId=&lt;id&gt; — the notes written against one
9	 * target, newest first. Scoped to a target (the detail page lists ITS notes), so the type and id
10	 * arrive as query parameters. Wired by officefloor/rest/api/notes.GET.yml.
11	 */
12	public class ListNotes {
13	
14	    public void service(@RequestParam("targetType") String targetType,
15	            @RequestParam("targetId") String targetId, NoteRepository notes,
16	            ObjectResponse<List<NoteView>> response) {
17	        List<NoteView> view = notes
18	                .findByTargetTypeAndTargetIdOrderByCreatedAtDescIdDesc(targetType,
19	                        Long.valueOf(targetId))
20	                .stream().map(NoteView::of).toList();
21	        response.send(view);
22	    }
23	}
24

1	package net.officefloor.hq.app;
2	
3	import net.officefloor.web.ObjectResponse;
4	import org.springframework.web.bind.annotation.RequestBody;
5	
6	/**
7	 * POST /api/notes — write a note against a target from the submitted type, id and text, returning
8	 * the saved row (with its generated id and write time). Wired by officefloor/rest/api/notes.POST.yml.
9	 *
10	 * A note must name a target and have something to say: we reject a blank target type, a missing
11	 * target id, or blank text before persisting. The write time is stamped by the server (now), so a
12	 * freshly written note sorts above every seeded one in the newest-first list.
13	 */
14	public class CreateNote {
15	
16	    public void service(@RequestBody NoteForm form, NoteRepository notes,
17	            ObjectResponse<NoteView> response) {
18	        String targetType = form.getTargetType() == null ? "" : form.getTargetType().trim();
19	        if (targetType.isEmpty()) {
20	            throw new IllegalArgumentException("A note target type is required");
21	        }
22	        Long targetId = form.getTargetId();
23	        if (targetId == null) {
24	            throw new IllegalArgumentException("A note target id is required");
25	        }
26	        String text = form.getText() == null ? "" : form.getText().trim();
27	        if (text.isEmpty()) {
28	            throw new IllegalArgumentException("Note text is required");
29	        }
30	        Note saved = notes.save(new Note(targetType, targetId, text));
31	        response.send(NoteView.of(saved));
32	    }
33	}
34

1	package net.officefloor.hq.app;
2	
3	import java.time.Instant;
4	import jakarta.persistence.Column;
5	import jakarta.persistence.Entity;
6	import jakarta.persistence.GeneratedValue;
7	import jakarta.persistence.GenerationType;
8	import jakarta.persistence.Id;
9	import jakarta.persistence.Table;
10	
11	/**
12	 * A free-text note the user writes against something. Maps the {@code notes} table (Flyway
13	 * V18__notes.sql); the id is IDENTITY-generated on create. The target is generic — a type
14	 * ({@code "project"}) plus the target row's id — so the same notes surface can sit on any entity.
15	 * {@code createdAt} is when the note was written; the detail page lists notes newest-first by it.
16	 */
17	@Entity
18	@Table(name = "notes")
19	public class Note {
20	
21	    @Id
22	    @GeneratedValue(strategy = GenerationType.IDENTITY)
23	    private Long id;
24	
25	    @Column(name = "target_type", nullable = false)
26	    private String targetType;
27	
28	    @Column(name = "target_id", nullable = false)
29	    private Long targetId;
30	
31	    @Column(nullable = false)
32	    private String text;
33	
34	    @Column(name = "created_at", nullable = false)
35	    private Instant createdAt;
36	
37	    protected Note() {
38	    }
39	
40	    public Note(String targetType, Long targetId, String text) {
41	        this.targetType = targetType;
42	        this.targetId = targetId;
43	        this.text = text;
44	        this.createdAt = Instant.now();
45	    }
46	
47	    public Long getId() {
48	        return id;
49	    }
50	
51	    public String getTargetType() {
52	        return targetType;
53	    }
54	
55	    public Long getTargetId() {
56	        return targetId;
57	    }
58	
59	    public String getText() {
60	        return text;
61	    }
62	
63	    public Instant getCreatedAt() {
64	        return createdAt;
65	    }
66	}
67

1	package net.officefloor.hq.app;
