5	/**
6	 * What the API exposes for a note: the shape the front-end renders into the notes list. {@code at}
7	 * is the write time as an instant (serialised ISO-8601); the server already returns the rows
8	 * newest-first, so the UI renders them in order without re-sorting.
9	 */
10	public record NoteView(Long id, String targetType, Long targetId, String text, Instant at) {
11	
12	    public static NoteView of(Note note) {
13	        return new NoteView(note.getId(), note.getTargetType(), note.getTargetId(), note.getText(),
14	                note.getCreatedAt());
15	    }
16	}
