1	import { Fragment, createElement } from 'react';
2	import type { ComponentType, ReactElement } from 'react';
3	import { forSlot } from './registry';
4	
5	// ── Slots: how features add UI without anything being edited ──────────────────────────────────
6	// A SLOT is a region of the UI that features fill. Whatever renders a region never lists what goes
7	// in it, so adding a panel, a table column, a row action, a toolbar control or a nav link is a NEW
8	// FILE and nothing existing is touched.
9	//
10	//   1. declare a region  ->  slots/defs/projectDetail.ts
11	//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
12	//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
13	//   3. fill it           ->  features/projects/notes.slot.tsx
14	//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
15	//
16	// This file, slots/registry.ts and slots/discover.ts are the mechanism — do not edit them. ADD a
17	// file under slots/defs/ to declare a new region.
18	
19	export type Contribution<Ctx> = {
20	  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
21	  order?: number;
22	  Component: ComponentType<Ctx>;
23	};
24	
25	export type SlotDef<Ctx extends object> = {
26	  id: string;
27	  /** Renders the region. Its props ARE the context handed to every contribution. */
28	  Slot: (ctx: Ctx) => ReactElement;
29	  /** A feature wraps its contribution in this, to be typed against the region's context. */
30	  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
31	};
32	
33	export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
34	  return {
35	    id,
36	    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
37	    // row actions are slots too), where a stray <div> would be invalid markup.
38	    Slot: (ctx: Ctx) =>
39	      createElement(
40	        Fragment,
41	        null,
42	        forSlot(id).map((c) =>
43	          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
44	        ),
45	      ),
46	    fill: (contribution) => ({ slot: id, ...contribution }),
47	  };
48	}
49

1	import { register } from './registry';
2	import type { Registered } from './registry';
3	
4	// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so no list of
5	// features exists anywhere. A file exports `contribution`, or `contributions` for more than one.
6	// Imported once, for its side effect, by main.tsx. Do not edit.
7	const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
8	  string,
9	  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
10	>;
11	
12	for (const [from, mod] of Object.entries(modules)) {
13	  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
14	  for (const c of declared) {
15	    register({ ...c, from, order: c.order ?? 0 });
16	  }
17	}
18

1	import type { ComponentType } from 'react';
2	
3	// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
4	// pulls in every feature's contribution file, and those files reach a slot definition, which
5	// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
6	// defs -> Slot -> registry) is what stops the module graph forming a cycle.
7	
8	export type Registered = {
9	  slot: string;
10	  order: number;
11	  /** Source file — the React key and the deterministic tie-break for equal `order`. */
12	  from: string;
13	  Component: ComponentType<never>;
14	};
15	
16	const contributions: Registered[] = [];
17	
18	/** Called once per contribution at startup, by slots/discover.ts. */
19	export function register(entry: Registered): void {
20	  contributions.push(entry);
21	}
22	
23	export function forSlot(id: string): Registered[] {
24	  return contributions
25	    .filter((c) => c.slot === id)
26	    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
27	}
