8	// The project's invoices and what they add up to — one panel filling the project.detail region.
9	// Reads server data under ['invoices', projectId] (never copied into state); the add form shares
10	// the key, so a successful add refreshes this with no import between them. The total is DERIVED
11	// from the same query (never stored), and amounts render with two decimals.
12	function ProjectInvoices({ projectId }: { projectId: number }) {
13	  // The ordering lives in the URL under the shared `invoiceSort` key — the sort control writes it,
14	  // this list reads it. It is part of the query key, so each ordering caches on its own and the
15	  // server returns the rows already sorted.
16	  const [sortParam] = useSearchParam('invoiceSort', asString);
17	  const sort: InvoiceSort = sortParam === 'due' ? 'due' : 'id';
18	  const { data: invoices } = useQuery({
19	    queryKey: [...invoicesKey(projectId), sort],
20	    queryFn: () => listInvoices(projectId, sort),
21	  });
22	
23	  if (!invoices) {
24	    return null;
25	  }
26	
27	  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);
28	
29	  return (
30	    <>
31	      <table data-testid="project-invoices-table">
32	        <thead>
33	          <tr>
34	            <th>Amount</th>
35	            <th>Status</th>
36	            <th>Issued</th>
37	            <th>Due</th>
38	            <th>Actions</th>
39	          </tr>
40	        </thead>
41	        <tbody>
42	          {invoices.map((invoice: Invoice) => (
43	            <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
44	              <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
45	              <td data-testid="invoice-status">{invoice.status}</td>
46	              <td data-testid="invoice-issued">{invoice.issuedDate}</td>
47	              <td data-testid="invoice-due">{invoice.dueDate}</td>
48	              <td>
49	                <InvoiceRow.Slot invoiceId={invoice.id} projectId={projectId} />
50	              </td>
51	            </tr>
52	          ))}
53	        </tbody>
54	      </table>
55	      <p data-testid="project-invoices-total">{formatMoney(total)}</p>
56	    </>
57	  );
58	}
59	
60	export const contribution = ProjectDetail.fill({ order: 20, Component: ProjectInvoices });
