1	import { useState } from 'react';
2	import { useMutation, useQueryClient } from '@tanstack/react-query';
3	import { ProjectDetail } from '../../slots/defs/projectDetail';
4	import { createInvoice, invoicesKey } from './api';
5	
6	// Add an invoice for an amount to this project — one panel filling the project.detail region. The
7	// amount the user is typing lives in useState (uncommitted input); the saved data lives on the
8	// server. On success we invalidate ['invoices', projectId] so the list + total refetch — we never
9	// hand-maintain the list.
10	function InvoiceForm({ projectId }: { projectId: number }) {
11	  const queryClient = useQueryClient();
12	  const [amount, setAmount] = useState('');
13	  const [error, setError] = useState('');
14	
15	  const mutation = useMutation({
16	    mutationFn: createInvoice,
17	    onSuccess: () => {
18	      setAmount('');
19	      void queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) });
20	    },
21	  });
22	
23	  const submit = (e: React.FormEvent) => {
24	    e.preventDefault();
25	    const value = Number(amount);
26	    if (amount.trim() === '' || Number.isNaN(value)) {
27	      return;
28	    }
29	    // An invoice must be for something: the amount has to be more than zero.
30	    if (value <= 0) {
31	      setError('Amount must be greater than zero');
32	      return;
33	    }
34	    setError('');
35	    mutation.mutate({ projectId, amount: value });
36	  };
37	
38	  return (
39	    <form onSubmit={submit}>
40	      <input
41	        data-testid="invoice-form-amount"
42	        placeholder="Amount"
43	        value={amount}
44	        onChange={(e) => setAmount(e.target.value)}
45	      />
46	      <button data-testid="invoice-form-submit" type="submit">
47	        Add invoice
48	      </button>
49	      {error && <p data-testid="invoice-form-amount-error">{error}</p>}
50	    </form>
51	  );
52	}
53	
54	export const contribution = ProjectDetail.fill({ order: 10, Component: InvoiceForm });
