3	// Every invoice across every project, as the API exposes it for the "all invoices" page. Each row
4	// carries its project's NAME (the cross-entity join done on the server) and its lifecycle stage
5	// (status), so the one list shows which project each invoice is for and what stage it is at without
6	// a second lookup. The query key ['invoices', 'all'] is its own handle — a send/pay write invalidates
7	// ['invoices'] by prefix, so this list refreshes in step with no import between them.
8	export type AllInvoice = {
9	  id: number;
10	  projectId: number;
11	  projectName: string;
12	  status: string;
13	  amount: number;
14	};
15	
16	export const allInvoicesKey = ['invoices', 'all'] as const;
17	
18	// How many invoices one page of the list shows. The server slices to this window; the pagination
19	// control steps through pages by the same count.
20	export const INVOICE_PAGE_SIZE = 10;
21	
22	// A single lifecycle stage to narrow the list to ('' means every stage) and which PAGE of the
23	// narrowed list to fetch (1-based). The server reads the same `status` and `page` the UI holds, so
24	// the narrowing and the windowing are applied once, at the source, not re-done on the client. Both
25	// are appended to the query key below so each stage/page caches on its own, while a send/pay write
26	// still invalidates ['invoices'] by prefix and refreshes whichever window is on screen.
27	export const listAllInvoices = (status = '', page = 1): Promise<AllInvoice[]> =>
28	  getJson<AllInvoice[]>(
29	    `/api/invoices/all?status=${encodeURIComponent(status)}` +
30	      `&page=${page}&pageSize=${INVOICE_PAGE_SIZE}`,
31	  );
