1	import { useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
4	import {
5	  lineItemsKey,
6	  listLineItems,
7	  removeLineItem,
8	  updateLineItem,
9	  lineAmount,
10	  type LineItem,
11	} from './lineItemsApi';
12	import { formatMoney } from '../../ui/money';
13	
14	// The invoice's line items — one panel filling the invoice.detail region (the money summary below it,
15	// subtotal / discount / total, is its own summary.slot.tsx). Reads server data under
16	// ['invoice-lineitems', invoiceId] (never copied into state); the add form shares the key, so a
17	// successful add refreshes this with no import between them. Each line can be CHANGED (inline) or
18	// REMOVED here: both are mutations that invalidate the same key so the list — and, by prefix, the
19	// summary's subtotal/total — refetch, plus ['invoices'] so the project's stored amount keeps step.
20	// Each line's amount is derived from the query (never stored), and money renders with two decimals.
21	// useState holds only what the user is currently typing into the row being edited.
22	function InvoiceLineItems({ invoiceId }: { invoiceId: number }) {
23	  const queryClient = useQueryClient();
24	  const { data: items } = useQuery({
25	    queryKey: lineItemsKey(invoiceId),
26	    queryFn: () => listLineItems(invoiceId),
27	  });
28	
29	  const [editingId, setEditingId] = useState<number | null>(null);
30	  const [description, setDescription] = useState('');
31	  const [qty, setQty] = useState('');
32	  const [unit, setUnit] = useState('');
33	  const [unitPrice, setUnitPrice] = useState('');
34	  const [error, setError] = useState('');
35	
36	  const refresh = () => {
37	    void queryClient.invalidateQueries({ queryKey: lineItemsKey(invoiceId) });
38	    void queryClient.invalidateQueries({ queryKey: ['invoices'] });
39	  };
40	
41	  const remove = useMutation({
42	    mutationFn: removeLineItem,
43	    onSuccess: refresh,
44	  });
45	
46	  const update = useMutation({
47	    mutationFn: updateLineItem,
48	    onSuccess: () => {
49	      setEditingId(null);
50	      setError('');
51	      refresh();
52	    },
53	  });
54	
55	  if (!items) {
56	    return null;
57	  }
58	
59	  const startEdit = (item: LineItem) => {
60	    setEditingId(item.id);
61	    setDescription(item.description);
62	    setQty(String(item.qty));
63	    setUnit(item.unit);
64	    setUnitPrice(String(item.unitPrice));
65	    setError('');
66	  };
67	
68	  const cancelEdit = () => {
69	    setEditingId(null);
70	    setError('');
71	  };
72	
73	  const saveEdit = (id: number) => {
74	    const qtyValue = Number(qty);
75	    const priceValue = Number(unitPrice);
76	    if (description.trim() === '') {
77	      setError('A description is required');
78	      return;
79	    }
80	    if (qty.trim() === '' || Number.isNaN(qtyValue) || qtyValue <= 0) {
81	      setError('Quantity must be greater than zero');
82	      return;
83	    }
84	    if (unitPrice.trim() === '' || Number.isNaN(priceValue) || priceValue < 0) {
85	      setError('Price each must be zero or more');
86	      return;
87	    }
88	    update.mutate({
89	      id,
90	      description: description.trim(),
91	      qty: qtyValue,
92	      unit: unit.trim() === '' ? 'units' : unit.trim(),
93	      unitPrice: priceValue,
94	    });
95	  };
96	
97	  return (
98	    <>
99	      <table data-testid="invoice-lineitems-table">
100	        <thead>
101	          <tr>
102	            <th>Description</th>
103	            <th>Qty</th>
104	            <th>Unit</th>
105	            <th>Unit price</th>
106	            <th>Amount</th>
107	            <th>Actions</th>
108	          </tr>
109	        </thead>
110	        <tbody>
111	          {items.map((item: LineItem) =>
112	            editingId === item.id ? (
113	              <tr key={item.id} data-testid={`lineitem-row-${item.id}`}>
114	                <td>
115	                  <input
116	                    data-testid={`lineitem-edit-description-${item.id}`}
117	                    value={description}
118	                    onChange={(e) => setDescription(e.target.value)}
119	                  />
120	                </td>
121	                <td>
122	                  <input
123	                    data-testid={`lineitem-edit-qty-${item.id}`}
124	                    value={qty}
125	                    onChange={(e) => setQty(e.target.value)}
126	                  />
127	                </td>
128	                <td>
129	                  <input
130	                    data-testid={`lineitem-edit-unit-${item.id}`}
131	                    value={unit}
132	                    onChange={(e) => setUnit(e.target.value)}
133	                  />
134	                </td>
135	                <td>
136	                  <input
137	                    data-testid={`lineitem-edit-unitprice-${item.id}`}
138	                    value={unitPrice}
139	                    onChange={(e) => setUnitPrice(e.target.value)}
140	                  />
141	                </td>
142	                <td data-testid="lineitem-amount">
143	                  {formatMoney(Number(qty) * Number(unitPrice))}
144	                </td>
145	                <td>
146	                  <button
147	                    data-testid={`lineitem-save-${item.id}`}
148	                    type="button"
149	                    onClick={() => saveEdit(item.id)}
150	                  >
151	                    Save
152	                  </button>
153	                  <button
154	                    data-testid={`lineitem-cancel-${item.id}`}
155	                    type="button"
156	                    onClick={cancelEdit}
157	                  >
158	                    Cancel
159	                  </button>
160	                </td>
161	              </tr>
162	            ) : (
163	              <tr key={item.id} data-testid={`lineitem-row-${item.id}`}>
164	                <td data-testid="lineitem-description">{item.description}</td>
165	                <td data-testid="lineitem-qty">{item.qty}</td>
166	                <td data-testid="lineitem-unit">{item.unit}</td>
167	                <td data-testid="lineitem-unitprice">{formatMoney(item.unitPrice)}</td>
168	                <td data-testid="lineitem-amount">{formatMoney(lineAmount(item))}</td>
169	                <td>
170	                  <button
171	                    data-testid={`lineitem-edit-${item.id}`}
172	                    type="button"
173	                    onClick={() => startEdit(item)}
174	                  >
175	                    Edit
176	                  </button>
177	                  <button
178	                    data-testid={`lineitem-remove-${item.id}`}
179	                    type="button"
180	                    onClick={() => remove.mutate(item.id)}
181	                  >
182	                    Remove
183	                  </button>
184	                </td>
185	              </tr>
186	            ),
187	          )}
188	        </tbody>
189	      </table>
190	      {error && <p data-testid="lineitem-edit-error">{error}</p>}
191	    </>
192	  );
193	}
194	
195	export const contribution = InvoiceDetail.fill({ order: 10, Component: InvoiceLineItems });
