2	
3	// A project as the API exposes it — it carries its client's NAME (the cross-entity join done on the
4	// server) so the list shows the client without a second lookup. The query key ['projects'] is the
5	// shared handle: the list reads it, the create form invalidates it.
6	export type Project = {
7	  id: number;
8	  name: string;
9	  clientId: number;
10	  clientName: string;
11	  archived: boolean;
12	  // Where the project sits in its lifecycle: ACTIVE, ON_HOLD or FINISHED. The row shows it; the
13	  // create form sets it.
14	  status: ProjectStatus;
15	  // The short reference code set when the project was created — shown on the row. Unique across
16	  // projects. Null only for projects that predate codes.
17	  code: string | null;
18	  tagIds: number[];
19	};
20	export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
21	export const projectStatuses: ProjectStatus[] = ['ACTIVE', 'ON_HOLD', 'FINISHED'];
22	export type NewProject = {
23	  name: string;
24	  clientId: number;
25	  status: ProjectStatus;
26	  code: string;
27	};
28	
29	export const projectsKey = ['projects'] as const;
30	
31	export const listProjects = (): Promise<Project[]> => getJson<Project[]>('/api/projects');
32	
33	export const createProject = (body: NewProject): Promise<Project> =>
34	  postJson<Project>('/api/projects', body);
35	
36	// Archive a project — tucks it away server-side (keeps the row, sets its archived flag) and returns
37	// the updated project. Callers invalidate ['projects'] on success so the list refetches and the row
38	// drops off, unless the archived ones are being shown.
39	export const archiveProject = (id: number): Promise<Project> =>
40	  postJson<Project>('/api/projects/archive', { id });
41	
42	// The client options the form's select needs: shared with the clients feature by the ['clients']
43	// KEY (not an import), so adding a client refreshes this select too.
44	export type ClientOption = { id: number; name: string };
45	export const clientsKey = ['clients'] as const;
46	export const listClientOptions = (): Promise<ClientOption[]> =>
47	  getJson<ClientOption[]>('/api/clients');
48

