3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoices references projects references clients, so H2 refuses to TRUNCATE a parent while
36	        // the FK exists — drop referential integrity for the duration, truncate all, then restore.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE dashboard_reference");
40	            jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE invoice_payments RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
47	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
48	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
49	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
50	        } finally {
51	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
52	        }
53	    }
54	
55	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
56	    @PostMapping("/seed")
57	    @SuppressWarnings("unchecked")
58	    public void seed(@RequestBody Map<String, Object> fixture) {
59	        // The reference date the dashboard measures "overdue" against (single row, id = 1). Optional:
60	        // a spec that does not care leaves it out, so the dashboard falls back to today.
61	        Object asOf = fixture.get("asOf");
62	        if (asOf != null) {
63	            jdbc.update("INSERT INTO dashboard_reference (id, as_of) VALUES (1, ?)",
64	                    java.sql.Date.valueOf(java.time.LocalDate.parse(asOf.toString())));
65	        }
66	        List<Map<String, Object>> clients =
67	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
68	        // Explicit ids from the fixture (the spec asserts rows by these ids), via JdbcTemplate.
69	        for (Map<String, Object> c : clients) {
70	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
71	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
72	        }
73	        List<Map<String, Object>> projects =
74	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
75	        for (Map<String, Object> p : projects) {
76	            // status is optional in the fixture — a spec that only cares a project exists leaves it
77	            // out, defaulting to ACTIVE (the same state a fresh project gets, V22__project_status.sql).
78	            Object status = p.getOrDefault("status", "ACTIVE");
79	            // archived is optional too — a spec that only cares a project exists leaves it out,
80	            // defaulting to not-archived (the same state a fresh project gets, V16__project_archived.sql).
81	            boolean archived = Boolean.TRUE.equals(p.getOrDefault("archived", Boolean.FALSE));
82	            // budget is optional in the fixture — a spec that does not care about the budget leaves
83	            // it out, so the column stays NULL (the same state a fresh project gets until one is set,
84	            // V23__project_budget.sql).
85	            java.math.BigDecimal budget = p.get("budget") != null
86	                    ? new java.math.BigDecimal(p.get("budget").toString())
87	                    : null;
88	            // code is optional in the fixture — a spec that does not care about the reference code
89	            // leaves it out, so the column stays NULL (V32__project_code.sql permits that for rows
90	            // predating codes); a spec asserting the code supplies it.
91	            Object code = p.get("code");
92	            jdbc.update(
93	                    "INSERT INTO projects (id, name, client_id, status, archived, budget, code)"
94	                            + " VALUES (?, ?, ?, ?, ?, ?, ?)",
95	                    ((Number) p.get("id")).longValue(), p.get("name"),
96	                    ((Number) p.get("clientId")).longValue(), status.toString(), archived, budget,
97	                    code != null ? code.toString() : null);
98	        }
99	        List<Map<String, Object>> contacts =
100	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
101	        for (Map<String, Object> c : contacts) {
102	            // primary is optional in the fixture — a spec that does not care leaves it out, so the
103	            // contact defaults to not-primary (the same state a fresh contact gets, V26__contact_primary.sql).
104	            boolean primary = Boolean.TRUE.equals(c.getOrDefault("primary", Boolean.FALSE));
105	            jdbc.update(
106	                    "INSERT INTO contacts (id, name, email, contact_role, client_id, is_primary)"
107	                            + " VALUES (?, ?, ?, ?, ?, ?)",
108	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"),
109	                    c.get("role"), ((Number) c.get("clientId")).longValue(), primary);
110	        }
111	        List<Map<String, Object>> invoices =
112	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
113	        for (Map<String, Object> inv : invoices) {
114	            Object status = inv.getOrDefault("status", "DRAFT");
115	            // Dates are optional in the fixture — a spec that only cares about the lifecycle leaves
116	            // them out, so default issued=today / due=+30 days (the same rule CreateInvoice applies).
117	            java.time.LocalDate issued = inv.get("issuedDate") != null
118	                    ? java.time.LocalDate.parse(inv.get("issuedDate").toString())
119	                    : java.time.LocalDate.now();
120	            java.time.LocalDate due = inv.get("dueDate") != null
121	                    ? java.time.LocalDate.parse(inv.get("dueDate").toString())
122	                    : issued.plusDays(30);
123	            // An invoice is built from line items; its amount is the sum of each line's qty times
124	            // unit price. A fixture gives the lines (not a figure), so compute the amount from them
125	            // here — the same derivation CreateLineItem keeps in step on every add. A legacy fixture
126	            // that still supplies an explicit amount (and no lines) is honoured as-is.
127	            List<Map<String, Object>> lineItems =
128	                    (List<Map<String, Object>>) inv.getOrDefault("lineItems", List.of());
129	            java.math.BigDecimal amount;
130	            if (inv.get("amount") != null) {
131	                amount = new java.math.BigDecimal(inv.get("amount").toString());
132	            } else {
133	                amount = java.math.BigDecimal.ZERO;
134	                for (Map<String, Object> li : lineItems) {
135	                    amount = amount.add(new java.math.BigDecimal(li.get("unitPrice").toString())
136	                            .multiply(new java.math.BigDecimal(li.get("qty").toString())));
137	                }
138	            }
139	            // discountPct is optional in the fixture — a spec that does not care about a discount
140	            // leaves it out, defaulting to 0 (the same state a fresh invoice gets until one is set,
141	            // V29__invoice_discount.sql), so the final total equals the subtotal.
142	            java.math.BigDecimal discountPct = inv.get("discountPct") != null
143	                    ? new java.math.BigDecimal(inv.get("discountPct").toString())
144	                    : java.math.BigDecimal.ZERO;
145	            // taxPct is optional in the fixture — a spec that does not care about tax leaves it out,
146	            // defaulting to 0 (the same state a fresh invoice gets until one is set,
147	            // V30__invoice_tax.sql), so the final total adds nothing on top of the discounted amount.
148	            java.math.BigDecimal taxPct = inv.get("taxPct") != null
149	                    ? new java.math.BigDecimal(inv.get("taxPct").toString())
150	                    : java.math.BigDecimal.ZERO;
151	            jdbc.update(
152	                    "INSERT INTO invoices"
153	                            + " (id, project_id, amount, status, issued_date, due_date, discount_pct, tax_pct)"
154	                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
155	                    ((Number) inv.get("id")).longValue(),
156	                    ((Number) inv.get("projectId")).longValue(),
157	                    amount,
158	                    status.toString(),
159	                    java.sql.Date.valueOf(issued),
160	                    java.sql.Date.valueOf(due),
161	                    discountPct,
162	                    taxPct);
163	            // Insert the invoice's lines with their explicit fixture ids (the spec asserts rows by
164	            // these ids), owned by this invoice.
165	            for (Map<String, Object> li : lineItems) {
166	                // unit is optional in the fixture — a spec that does not care leaves it out, so the
167	                // line defaults to a neutral "units" (the same fallback CreateLineItem applies).
168	                Object unit = li.getOrDefault("unit", "units");
169	                jdbc.update(
170	                        "INSERT INTO invoice_line_items"
171	                                + " (id, invoice_id, description, quantity, unit, unit_price)"
172	                                + " VALUES (?, ?, ?, ?, ?, ?)",
173	                        ((Number) li.get("id")).longValue(),
174	                        ((Number) inv.get("id")).longValue(),
175	                        li.get("description"),
176	                        ((Number) li.get("qty")).intValue(),
177	                        unit.toString(),
178	                        new java.math.BigDecimal(li.get("unitPrice").toString()));
179	            }
180	        }
181	        // Payments a client has made against an invoice (amount + the date paid), with their
182	        // explicit fixture ids (the spec asserts rows by these ids), owned by a seeded invoice.
183	        List<Map<String, Object>> payments =
184	                (List<Map<String, Object>>) fixture.getOrDefault("payments", List.of());
185	        long maxPaymentId = 0;
186	        for (Map<String, Object> pay : payments) {
187	            long paymentId = ((Number) pay.get("id")).longValue();
188	            jdbc.update(
189	                    "INSERT INTO invoice_payments (id, invoice_id, amount, paid_date)"
190	                            + " VALUES (?, ?, ?, ?)",
191	                    paymentId,
192	                    ((Number) pay.get("invoiceId")).longValue(),
193	                    new java.math.BigDecimal(pay.get("amount").toString()),
194	                    java.sql.Date.valueOf(
195	                            java.time.LocalDate.parse(pay.get("date").toString())));
196	            maxPaymentId = Math.max(maxPaymentId, paymentId);
197	        }
198	        // Explicit ids (GENERATED BY DEFAULT) do NOT advance H2's identity sequence, so a payment
199	        // recorded through the API would collide on id 1. Bump the sequence past the seeded rows.
200	        if (maxPaymentId > 0) {
201	            jdbc.execute(
202	                    "ALTER TABLE invoice_payments ALTER COLUMN id RESTART WITH " + (maxPaymentId + 1));
203	        }
204	        List<Map<String, Object>> tasks =
205	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
206	        for (Map<String, Object> t : tasks) {
207	            // done is optional in the fixture — a spec that only cares a task exists leaves it out,
208	            // so it defaults to not-done (the same state CreateTask would give a fresh task).
209	            boolean done = Boolean.TRUE.equals(t.getOrDefault("done", Boolean.FALSE));
210	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
211	                    ((Number) t.get("id")).longValue(),
212	                    ((Number) t.get("projectId")).longValue(),
213	                    t.get("title"), done);
214	        }
215	        List<Map<String, Object>> tags =
216	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
217	        for (Map<String, Object> tag : tags) {
218	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
219	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
220	        }
221	        // Notes are written against a generic target (type + id); the fixture pins each note's
222	        // write time so the newest-first order is deterministic. `at` is optional — a spec that
223	        // only cares a note exists leaves it out, defaulting to now().
224	        List<Map<String, Object>> notes =
225	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
226	        long maxNoteId = 0;
227	        for (Map<String, Object> n : notes) {
228	            java.time.OffsetDateTime at = n.get("at") != null
229	                    ? java.time.OffsetDateTime.parse(n.get("at").toString())
230	                    : java.time.OffsetDateTime.now();
231	            long noteId = ((Number) n.get("id")).longValue();
232	            jdbc.update(
233	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
234	                            + " VALUES (?, ?, ?, ?, ?)",
235	                    noteId,
236	                    n.get("targetType"),
237	                    ((Number) n.get("targetId")).longValue(),
238	                    n.get("text"),
239	                    at);
240	            maxNoteId = Math.max(maxNoteId, noteId);
241	        }
242	        // Explicit ids (GENERATED BY DEFAULT) do NOT advance H2's identity sequence, so the app's
243	        // next create would collide on id 1. Bump the sequence past the seeded rows so a note added
244	        // through the API gets a fresh id above them.
245	        if (maxNoteId > 0) {
246	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
247	        }
248	        // The many-to-many links: which seeded tag sits on which seeded project.
249	        List<Map<String, Object>> projectTags =
250	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
251	        for (Map<String, Object> pt : projectTags) {
252	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
253	                    ((Number) pt.get("projectId")).longValue(),
254	                    ((Number) pt.get("tagId")).longValue());
255	        }
256	    }
257	}
